{"implementation": "def solve(case):
    if not isinstance(case, dict):
        raise TypeError("case must be an object")
    if "nodes" not in case or "required_symbols" not in case:
        raise ValueError("case is missing required fields")

    nodes = case["nodes"]
    required_symbols = case["required_symbols"]
    if not isinstance(nodes, list):
        raise TypeError("nodes must be a list")
    if not isinstance(required_symbols, list):
        raise TypeError("required_symbols must be a list")
    if not all(isinstance(symbol, str) for symbol in required_symbols):
        raise TypeError("required_symbols must contain only strings")

    by_id = {}
    order_index = {}
    for index, node in enumerate(nodes):
        if not isinstance(node, dict):
            raise TypeError("each node must be an object")
        for field in ("id", "parent", "symbol", "depth", "removable", "utility"):
            if field not in node:
                raise ValueError("node is missing required field: " + field)
        node_id = node["id"]
        if not isinstance(node_id, str):
            raise TypeError("node id must be a string")
        if node_id in by_id:
            raise ValueError("duplicate node id")
        if node["parent"] is not None and not isinstance(node["parent"], str):
            raise TypeError("node parent must be null or a string")
        if not isinstance(node["symbol"], str):
            raise TypeError("node symbol must be a string")
        if not isinstance(node["depth"], int) or isinstance(node["depth"], bool):
            raise TypeError("node depth must be an integer")
        if not isinstance(node["removable"], bool):
            raise TypeError("node removable must be a boolean")
        if not isinstance(node["utility"], (int, float)) or isinstance(node["utility"], bool):
            raise TypeError("node utility must be numeric")
        by_id[node_id] = node
        order_index[node_id] = index

    children = {node_id: [] for node_id in by_id}
    root_ids = set()
    for node in nodes:
        node_id = node["id"]
        parent = node["parent"]
        if parent is None:
            root_ids.add(node_id)
        else:
            if parent not in by_id:
                raise ValueError("node parent references an unknown id")
            children[parent].append(node_id)

    retained = set(by_id)
    removed_order = []
    required = set(required_symbols)

    def required_symbols_still_present(without_id):
        present = set()
        for node in nodes:
            node_id = node["id"]
            if node_id != without_id and node_id in retained:
                present.add(node["symbol"])
        return required.issubset(present)

    candidates = sorted(nodes, key=lambda node: (-node["depth"], node["id"]))
    for node in candidates:
        node_id = node["id"]
        if node_id not in retained:
            continue
        if node_id in root_ids:
            continue
        if not node["removable"]:
            continue
        if node["symbol"] in required:
            continue
        if any(child_id in retained for child_id in children[node_id]):
            continue
        if not required_symbols_still_present(node_id):
            continue
        retained.remove(node_id)
        removed_order.append(node_id)

    return {
        "removed_node_ids": removed_order,
        "retained_node_ids": sorted(retained),
    }
"}
